RADAR_FILE_00
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "Dockerfile"
cat > "Dockerfile" <<'RADAR_FILE_01'
FROM python:3.11-slim

ARG TZ=Europe/Saratov
ENV PYTHONUNBUFFERED=1 \
    PYTHONDONTWRITEBYTECODE=1 \
    PIP_NO_CACHE_DIR=1 \
    TZ=${TZ}

# ffmpeg нужен для склейки видео и звука выше 720p. Он заметно увеличивает
# образ (~150 МБ); если загрузка видео не нужна, его можно убрать.
# fonts-dejavu-core — для погоды картинкой: в python:3.11-slim шрифтов нет
# вообще, а встроенный шрифт Pillow кириллицу не покрывает и растровый,
# отчего сводка выходила нечитаемой. Пакет весит около 2 МБ.
RUN apt-get update \
 && apt-get install -y --no-install-recommends tzdata ca-certificates ffmpeg fonts-dejavu-core \
 && ln -snf /usr/share/zoneinfo/$TZ /etc/localtime \
 && echo $TZ > /etc/timezone \
 && rm -rf /var/lib/apt/lists/*

WORKDIR /app

COPY requirements.txt .
RUN pip install --no-cache-dir -r requirements.txt

COPY main.py alembic.ini ./
# Диагностика лежит внутри пакета: tools/ исключён из контекста сборки
COPY radar ./radar
COPY migrations ./migrations

RUN useradd -m -u 1000 radar && mkdir -p /app/data && chown -R radar:radar /app
USER radar

CMD ["python", "-u", "main.py"]
RADAR_FILE_01
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "docker-compose.yml"
cat > "docker-compose.yml" <<'RADAR_FILE_02'
# Сборка рассчитана на одноплатник с 1–2 ГБ памяти.
# По умолчанию база — SQLite: файл рядом с ботом, отдельный контейнер не нужен.
# PostgreSQL включается профилем, когда бот переезжает на машину помощнее:
#   DB_BACKEND=postgres docker compose --profile postgres up -d

services:
  radar:
    build:
      context: .
      args:
        TZ: ${TZ:-Europe/Saratov}
    image: radar_image
    container_name: radar_container
    # unless-stopped, а не on-failure: с on-failure контейнер не поднимался
    # после штатной остановки и после перезагрузки сервера — бот оставался
    # выключенным молча. Для системы оповещения это хуже цикла рестартов,
    # тем более что от него защищает диагностика: при неверной конфигурации
    # установщик просто не запускает бота.
    restart: unless-stopped
    env_file: .env
    # Порт веб-панели. По умолчанию слушает только localhost: панель
    # с доступом снаружи обязана стоять за HTTPS, иначе cookie сессии
    # уходит открытым текстом. Чтобы открыть наружу, поставьте
    # WEB_BIND=0.0.0.0 и обязательно WEB_HTTPS=1 с reverse proxy.
    ports:
      - "${WEB_BIND:-127.0.0.1}:${WEB_PORT:-8080}:${WEB_PORT:-8080}"
    volumes:
      - ./data:/app/data
      # .env смонтирован, а не только передан через env_file. Без этого
      # бот читал ключи из окружения, которое Compose впрыскивает ОДИН РАЗ,
      # при создании контейнера: правка .env на хосте не действовала до
      # пересоздания, а правка ключа из бота уходила в файл внутри
      # контейнера и пропадала при первом же обновлении. Найдено на живом
      # сервере: сократитель выдавал домен, стёртый из .env двумя днями
      # раньше. Файл обязан существовать до запуска — иначе Docker создаст
      # на его месте каталог; установщик создаёт .env раньше сборки.
      - ./.env:/app/.env
      # Общий том с Bot API Server: в локальном режиме он читает файлы
      # прямо с диска, без передачи по HTTP
      - ./data/bot-api:/var/lib/telegram-bot-api
    deploy:
      resources:
        limits:
          memory: ${RADAR_MEM_LIMIT:-512M}
    logging:
      driver: json-file
      options:
        max-size: "10m"
        max-file: "3"

  # Собственный Bot API Server: снимает предел отправки с 50 МБ до 2 ГБ.
  # Включается профилем, когда нужна загрузка крупных видео:
  #   docker compose --profile media up -d
  # Требует api_id и api_hash с my.telegram.org.
  telegram-bot-api:
    profiles: ["media"]
    image: aiogram/telegram-bot-api:latest
    container_name: radar_bot_api
    restart: unless-stopped
    environment:
      # Пустые значения по умолчанию обязательны: Compose подставляет
      # переменные во всём файле независимо от профилей, и конструкция
      # ${VAR:?...} роняла бы обычную сборку, где этот сервис не нужен.
      # Отсутствие ключей проверяет установщик при включении профиля media.
      TELEGRAM_API_ID: ${TELEGRAM_API_ID:-}
      TELEGRAM_API_HASH: ${TELEGRAM_API_HASH:-}
      TELEGRAM_LOCAL: "true"
    command:
      # Кэш сервера растёт быстро: чистим файлы старше 6 часов
      - --max-file-age=21600
      # И принудительно, если на диске осталось меньше 15 процентов
      - --dir-cleanup-threshold=15
      - --local
    volumes:
      - ./data/bot-api:/var/lib/telegram-bot-api
    deploy:
      resources:
        limits:
          memory: 512M
    logging:
      driver: json-file
      options:
        max-size: "10m"
        max-file: "3"

  # Выход в сеть через внешний узел. Поднимается профилем, когда
  # суперадминистратор выбрал сервер в боте:
  #   docker compose --profile proxy up -d
  # Конфигурация пишется ботом в data/singbox/config.json.
  singbox:
    profiles: ["proxy"]
    image: ghcr.io/sagernet/sing-box:latest
    container_name: radar_singbox
    restart: unless-stopped
    command: ["run", "-c", "/etc/sing-box/config.json"]
    volumes:
      - ./data/singbox:/etc/sing-box:ro
    deploy:
      resources:
        limits:
          memory: 128M
    logging:
      driver: json-file
      options:
        max-size: "5m"
        max-file: "2"

  postgres:
    profiles: ["postgres"]
    image: postgres:16-alpine
    container_name: radar_db
    restart: unless-stopped
    environment:
      POSTGRES_DB: ${DB_NAME:-radar}
      POSTGRES_USER: ${DB_USER:-radar}
      POSTGRES_PASSWORD: ${DB_PASSWORD:-radar}
      POSTGRES_INITDB_ARGS: "--encoding=UTF8 --locale=C"
    # Значения подобраны под 1–2 ГБ ОЗУ. На машине с 4 ГB и больше
    # можно поднять shared_buffers до 256MB, а effective_cache_size до 1GB.
    command: >
      postgres
      -c shared_buffers=96MB
      -c effective_cache_size=256MB
      -c work_mem=4MB
      -c maintenance_work_mem=32MB
      -c max_connections=20
      -c max_parallel_workers=0
      -c max_parallel_workers_per_gather=0
      -c max_worker_processes=2
      -c wal_compression=on
      -c synchronous_commit=off
    volumes:
      - ./data/postgres:/var/lib/postgresql/data
    shm_size: 64mb
    deploy:
      resources:
        limits:
          memory: 512M
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U ${DB_USER:-radar} -d ${DB_NAME:-radar}"]
      interval: 10s
      timeout: 5s
      retries: 10
      start_period: 30s
    logging:
      driver: json-file
      options:
        max-size: "10m"
        max-file: "3"
RADAR_FILE_02
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "alembic.ini"
cat > "alembic.ini" <<'RADAR_FILE_03'
[alembic]
script_location = migrations
prepend_sys_path = .
version_path_separator = os

[loggers]
keys = root,sqlalchemy,alembic

[handlers]
keys = console

[formatters]
keys = generic

[logger_root]
level = WARNING
handlers = console
qualname =

[logger_sqlalchemy]
level = WARNING
handlers =
qualname = sqlalchemy.engine

[logger_alembic]
level = INFO
handlers =
qualname = alembic

[handler_console]
class = StreamHandler
args = (sys.stderr,)
level = NOTSET
formatter = generic

[formatter_generic]
format = %(levelname)-5.5s [%(name)s] %(message)s
datefmt = %H:%M:%S
