@dataclass(frozen=True)
class Case:
    ident: str
    text: str
    categories: tuple[str, ...]
    streets: tuple[str, ...] = ()
    sensitive: bool = False


CASES: tuple[Case, ...] = (
    Case("jkh", "Внимание! Отключение холодной воды по улице Чапаева, дома 12 и 14 "
                "до 18:00 в связи с устранением порыва.",
