printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "radar/backup.py"
cat > "radar/backup.py" <<'RADAR_FILE_37'
"""Резервные копии проекта: база, настройки, данные.

Один модуль на два контура — бот и веб-панель делают одно и то же, поэтому
логика здесь, а не продублирована в обработчиках.

Что попадает в копию: база (SQLite целиком с журналами WAL или дамп
PostgreSQL), файл `.env`, выгрузка источников, версия проекта. Журналы
не берём: они объёмные и восстановление от них не зависит.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import asyncio
import logging
import os
import shutil
import tarfile
import time
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

from . import config

log = logging.getLogger("radar.backup")

KEEP = 10

# Внутри data/, а не рядом с кодом. Каталог с кодом в контейнере
# не смонтирован наружу: копии, снятые ботом, лежали в /app/backups
# и исчезали при первом же пересоздании контейнера — то есть при
# каждом обновлении. Вместе с ними пропадали и копии .env, которые
# снимаются перед правкой ключа, ради страховки. data/ смонтирован
# на хост, поэтому копии переживают обновление.
DIRECTORY = "data/backups"


@dataclass
class Archive:
    path: Path
    size: int
    created: float

    @property
    def name(self) -> str:
        return self.path.name

    @property
    def size_human(self) -> str:
        value = float(self.size)
        for unit in ("Б", "КБ", "МБ", "ГБ"):
            if value < 1024 or unit == "ГБ":
                return f"{value:.0f} {unit}" if unit == "Б" else f"{value:.1f} {unit}"
            value /= 1024
        return f"{value:.1f} ГБ"

    @property
    def when(self) -> str:
        return f"{datetime.fromtimestamp(self.created):%d.%m.%Y %H:%M}"


def directory() -> Path:
    path = Path(DIRECTORY)
    path.mkdir(parents=True, exist_ok=True)
    return path


def listing() -> list[Archive]:
    """Копии, новые сверху."""
    items: list[Archive] = []
    for path in directory().glob("radar-backup-*.tar.gz"):
        try:
            stat = path.stat()
        except OSError:
            continue
        items.append(Archive(path, stat.st_size, stat.st_mtime))
    return sorted(items, key=lambda item: item.created, reverse=True)


def find(name: str) -> Path | None:
    """Ищет копию по имени. Имя проверяется — иначе можно уйти из каталога."""
    if not name or "/" in name or "\\" in name or name.startswith("."):
        return None
    target = directory() / name
    return target if target.exists() and target.is_file() else None


def _dump_postgres(destination: Path) -> bool:
    """Дамп PostgreSQL через контейнер. Без него копия бесполезна."""
    import subprocess

    try:
        with destination.open("wb") as handle:
            result = subprocess.run(
                ["docker", "exec", "radar_db", "pg_dump", "-U", config.DB_USER,
                 config.DB_NAME],
                stdout=handle, stderr=subprocess.PIPE, timeout=300, check=False,
            )
        if result.returncode == 0:
            return True
        log.warning("pg_dump вернул %s: %s", result.returncode,
                    result.stderr.decode("utf-8", "replace")[:200])
    except Exception as exc:  # noqa: BLE001
        log.warning("Дамп PostgreSQL не выполнен: %s", exc)
    destination.unlink(missing_ok=True)
    return False


def _collect(staging: Path, reason: str) -> None:
    """Складывает во временный каталог всё, что должно попасть в копию."""
    staging.mkdir(parents=True, exist_ok=True)

    if config.is_sqlite():
        source = Path(config.DB_FILE)
        for suffix in ("", "-wal", "-shm"):
            candidate = Path(f"{source}{suffix}")
            if candidate.exists():
                shutil.copy2(candidate, staging / candidate.name)
    else:
        _dump_postgres(staging / "database.sql")

    env_path = Path(".env")
    if env_path.exists():
        shutil.copy2(env_path, staging / "env.backup")

    legacy = Path("data/db.json")
    if legacy.exists():
        shutil.copy2(legacy, staging / "db.json")

    manifest = staging / "manifest.txt"
    manifest.write_text(
        f"Система «Радар»\n"
        f"Версия: {config.VERSION}\n"
        f"Дата: {datetime.now():%Y-%m-%d %H:%M:%S}\n"
        f"База: {'SQLite' if config.is_sqlite() else 'PostgreSQL'}\n"
        f"Причина: {reason}\n",
        encoding="utf-8",
    )


def _prune() -> None:
    for extra in listing()[KEEP:]:
        try:
            extra.path.unlink()
        except OSError:
            pass


def create_sync(reason: str = "вручную") -> tuple[Path | None, str]:
    """Собирает копию. Возвращает (путь, ошибка)."""
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    archive = directory() / f"radar-backup-{config.VERSION}-{stamp}.tar.gz"
    staging = directory() / f".staging-{stamp}"

    try:
        _collect(staging, reason)
        with tarfile.open(archive, "w:gz") as bundle:
            for item in staging.iterdir():
                bundle.add(item, arcname=item.name)
    except Exception as exc:  # noqa: BLE001
        log.error("Копия не создана: %s", exc)
        archive.unlink(missing_ok=True)
        return None, str(exc)[:200]
    finally:
        shutil.rmtree(staging, ignore_errors=True)

    _prune()
    log.info("Копия создана: %s (%d КБ)", archive.name, archive.stat().st_size // 1024)
    return archive, ""


async def create(reason: str = "вручную") -> tuple[Path | None, str]:
    """Асинхронная обёртка: упаковка блокирует, уводим в поток."""
    return await asyncio.to_thread(create_sync, reason)


def backup_env() -> Path | None:
    """Копия .env перед изменением ключей.

    Отдельная и дешёвая: правка ключа через бот не должна требовать полной
    копии проекта, но и потерять прежние значения нельзя.
    """
    source = Path(config.ENV_FILE if hasattr(config, "ENV_FILE") else ".env")
    if not source.exists():
        return None
    target = directory() / f"env-{datetime.now():%Y%m%d-%H%M%S}.backup"
    try:
        shutil.copy2(source, target)
        os.chmod(target, 0o600)
    except OSError as exc:
        log.warning("Копия .env не создана: %s", exc)
        return None

    # Держим последние 10 копий настроек
    old = sorted(directory().glob("env-*.backup"), key=lambda item: item.stat().st_mtime)
    for extra in old[:-10]:
        extra.unlink(missing_ok=True)
    return target


def summary() -> str:
    """Состояние копий для сообщения в боте."""
    items = listing()
    if not items:
        return (
            "💾 <b>Резервные копии</b>\n\nКопий пока нет.\n\n"
            "<i>Копия включает базу целиком, файл настроек и версию проекта.</i>"
        )

    total = sum(item.size for item in items)
    lines = [
        "💾 <b>Резервные копии</b>",
        f"Всего: <b>{len(items)}</b>, объём {total // 1024} КБ",
        "",
    ]
    for item in items[:10]:
        lines.append(f"• <code>{item.name}</code>\n  {item.when} · {item.size_human}")
    lines.append("")
    lines.append(
        "<i>Хранятся последние 10. Восстановление — установщиком: "
        "<code>bash install.sh --rollback</code></i>"
    )
    return "\n".join(lines)


# --------------------------------------------------------------------------
#  Расписание и ротация (с 4.7.3.5)
# --------------------------------------------------------------------------
#
# Копия, которую снимают руками, снимается ровно до того дня, когда о ней
# забывают. Поэтому расписание — не удобство, а условие того, что копия
# вообще будет существовать в момент аварии.
#
# Ротация обязательна по той же причине, что и расписание: без неё копии
# заполнят диск одноплатника за несколько недель, и первым сломается
# не резервное копирование, а сам бот — места не останется под базу.

KEEP_COPIES = 7          # недельная глубина при ежедневных копиях
SCHEDULE_HOUR = 4        # ночью: сжатие базы заметно нагружает слабый процессор


def rotate(keep: int = KEEP_COPIES) -> list[str]:
    """Удаляет самые старые копии сверх лимита. Возвращает удалённые имена."""
    archives = listing()
    if len(archives) <= keep:
        return []

    removed: list[str] = []
    # listing() отдаёт от новых к старым, значит лишние — в хвосте.
    for archive in archives[keep:]:
        try:
            Path(archive.path).unlink()
            removed.append(archive.name)
        except OSError as exc:
            log.warning("Не удалось удалить копию %s: %s", archive.name, exc)
    if removed:
        log.info("Ротация копий: удалено %d", len(removed))
    return removed


def due_today(last_run: str, now: datetime) -> bool:
    """Пора ли снимать копию.

    Сравниваем по дате, а не по часам: если сервер был выключен в четыре
    утра, копия должна сняться при первой возможности, а не пропасть
    до следующих суток.
    """
    if now.hour < SCHEDULE_HOUR:
        return False
    return last_run != now.strftime("%Y-%m-%d")


async def run_scheduled(now: datetime) -> str:
    """Ежедневная копия с ротацией. Возвращает пустую строку, если не время."""
    from . import features
    from .db import repo

    if not features.enabled("backup_schedule"):
        return ""

    try:
        last_run = str(await repo.get_meta("backup_last_run", "") or "")
    except Exception:  # noqa: BLE001
        log.exception("Не удалось прочитать отметку о копии")
        return ""

    if not due_today(last_run, now):
        return ""

    path, note = await create("по расписанию")
    try:
        await repo.set_meta("backup_last_run", now.strftime("%Y-%m-%d"))
    except Exception:  # noqa: BLE001
        # Отметку не записали — завтра снимется ещё одна копия.
        # Это лучше, чем не снять ни одной, поэтому не считаем ошибкой.
        log.warning("Отметка о копии не сохранилась")

    if path is None:
        log.error("Копия по расписанию не создана: %s", note)
        return ""

    removed = rotate()
    log.info("Копия по расписанию: %s, удалено старых: %d", path.name, len(removed))
    return path.name
RADAR_FILE_37
printf "  %s·%s %s\n" "$C_DIM" "$C_RESET" "radar/dbcare.py"
cat > "radar/dbcare.py" <<'RADAR_FILE_38'
"""Компактность базы: чистка истории, сжатие файла, контроль размера.

Пункт 5 раздела 4.8. Три отдельные задачи, и каждая нужна по своей
причине.

**Чистка истории.** `purge_old_events` существовала с 4.0, но вызывалась
только при старте. Бот, работающий месяцами без перезапуска, не чистил
историю вовсе — а это ровно тот режим, ради которого он написан.

**Сжатие файла.** Здесь суть, которую легко упустить: **SQLite не отдаёт
место операционной системе после DELETE.** Строки помечаются свободными
и переиспользуются внутри файла, но сам файл не уменьшается никогда.
То есть чистка истории без `VACUUM` не освобождает ни байта на диске —
она лишь замедляет дальнейший рост. На одноплатнике, где место кончается
раньше терпения, это разница между «работает» и «база не пишется».

**PostgreSQL сжимаем иначе — то есть не сжимаем.** Там есть autovacuum,
который делает то же самое сам, а `VACUUM FULL` берёт исключительную
блокировку на всю таблицу: для системы оповещения это недопустимо.
Поэтому явное сжатие делается только для SQLite.

**Когда сжимать.** Только после того, как что-то действительно удалено:
`VACUUM` переписывает файл целиком и на большой базе занимает время,
в течение которого база заблокирована. Гонять его вхолостую каждую ночь
значило бы платить блокировкой ни за что.

**Место на диске.** `VACUUM` строит новый файл рядом со старым, поэтому
на время работы нужно вдвое больше места. Если его нет, сжатие
пропускается: попытка «освободить место» не должна быть тем, что
переполнит диск окончательно.
"""

# --------------------------------------------------------------------------
# Система «Радар» — мониторинг городских угроз и аварий ЖКХ
# Автор: SecretHero · https://github.com/Chistovik92/radar
# Лицензия: GPL-3.0
# --------------------------------------------------------------------------

from __future__ import annotations

import logging
import os
from datetime import datetime

log = logging.getLogger("radar.dbcare")

# Ночью: переписывание файла заметно нагружает слабый процессор,
# а в четыре утра городские каналы молчат.
SCHEDULE_HOUR = 4
# Порог предупреждения. Полгигабайта на одноплатнике — уже повод
# посмотреть, что происходит: при обычной нагрузке база столько
# не набирает.
WARN_SIZE_MB = 500
# Ниже этого размера сжимать нечего: выигрыш меньше, чем стоимость
# блокировки.
MIN_VACUUM_MB = 5


def due_today(last_run: str, now: datetime) -> bool:
    """Пора ли обслуживать базу.

    Сравнение по дате, а не по часам: если сервер был выключен в четыре
    утра, обслуживание пройдёт при первой возможности, а не пропадёт
    до следующих суток. Та же логика, что у резервных копий.
    """
    if now.hour < SCHEDULE_HOUR:
        return False
    return last_run != now.strftime("%Y-%m-%d")


def format_size(size_bytes: float) -> str:
    """«12.4 МБ» — человеку нужен порядок, а не байты."""
    units = (("ГБ", 1024 ** 3), ("МБ", 1024 ** 2), ("КБ", 1024))
    for name, scale in units:
        if size_bytes >= scale:
            return f"{size_bytes / scale:.1f} {name}"
    return f"{int(size_bytes)} Б"


def sqlite_files(path: str) -> list[str]:
    """Файл базы и его спутники.

    В режиме WAL рядом лежат `-wal` и `-shm`, и журнал может весить
    больше самой базы. Считать только основной файл — значит показывать
    размер, не совпадающий с тем, что видно в `du`.
    """
    return [path, f"{path}-wal", f"{path}-shm"]


def measure_sqlite(path: str) -> int:
    """Суммарный размер базы SQLite в байтах. Нет файла — ноль."""
    total = 0
    for name in sqlite_files(path):
        try:
            total += os.path.getsize(name)
        except OSError:
            continue
    return total


def free_space(path: str) -> float:
    """Свободно байт там, где лежит база. Неизвестно — бесконечность."""
    import shutil

    probe = os.path.dirname(os.path.abspath(path)) or "."
    try:
        return float(shutil.disk_usage(probe).free)
    except OSError:
        return float("inf")


def can_vacuum(size_bytes: int, free_bytes: float) -> tuple[bool, str]:
    """Хватит ли места на сжатие и есть ли в нём смысл.

    `VACUUM` строит новый файл рядом со старым — нужно вдвое больше
    места. Попытка освободить место не должна стать тем, что окончательно
    переполнит диск.
    """
    if size_bytes < MIN_VACUUM_MB * 1024 * 1024:
        return False, "база меньше порога — сжимать нечего"
    if free_bytes < size_bytes * 2:
        return False, (
            f"нужно {format_size(size_bytes * 2)} свободного места, "
            f"а есть {format_size(free_bytes)}"
        )
    return True, ""


def size_report(size_bytes: int, backend: str) -> str:
    """Строка о размере базы для отчёта и предупреждения."""
    text = f"База ({backend}): {format_size(size_bytes)}"
    if size_bytes >= WARN_SIZE_MB * 1024 * 1024:
        text += (
            f"\n⚠️ Это больше {WARN_SIZE_MB} МБ. Проверьте "
            f"EVENT_RETENTION_DAYS и место на диске."
        )
    return text


async def vacuum_sqlite() -> tuple[int, int, str]:
    """Сжимает базу. Возвращает (было, стало, объяснение отказа).

    Перед сжатием переносим журнал WAL в основной файл: иначе `-wal`
    остаётся раздутым, и суммарный размер почти не меняется — самая
    обидная разновидность «сделали и не помогло».
    """
    from . import config
    from .db import engine as db_engine

    path = config.DB_FILE
    before = measure_sqlite(path)

    allowed, why = can_vacuum(before, free_space(path))
    if not allowed:
        return before, before, why

    try:
        from sqlalchemy import text

        raw = db_engine.get_engine()
        # VACUUM не выполняется внутри транзакции, поэтому нужен режим
        # AUTOCOMMIT — иначе SQLAlchemy обернёт его в BEGIN и получит
        # «cannot VACUUM from within a transaction».
        async with raw.connect() as connection:
            await connection.execution_options(isolation_level="AUTOCOMMIT")
            await connection.execute(text("PRAGMA wal_checkpoint(TRUNCATE)"))
            await connection.execute(text("VACUUM"))
    except Exception as exc:  # noqa: BLE001
        log.warning("Сжатие базы не удалось: %s", exc)
        return before, measure_sqlite(path), "сжатие не удалось, подробности в журнале"

    after = measure_sqlite(path)
    log.info("База сжата: %s -> %s", format_size(before), format_size(after))
    return before, after, ""


async def run_scheduled(now: datetime) -> str:
    """Ежедневное обслуживание. Пустая строка — не время или нечего делать."""
    from . import config
    from .db import repo

    try:
        last_run = str(await repo.get_meta("dbcare_last_run", "") or "")
    except Exception:  # noqa: BLE001
        log.exception("Не удалось прочитать отметку об обслуживании базы")
        return ""

    if not due_today(last_run, now):
        return ""

    parts: list[str] = []

    try:
        removed = await repo.purge_old_events()
    except Exception:  # noqa: BLE001
        log.exception("Чистка истории не удалась")
        removed = 0
    if removed:
        parts.append(f"удалено событий: {removed}")

    # Сжимаем только SQLite и только если что-то удалено: VACUUM
    # переписывает файл целиком и на время блокирует базу. Гонять его
    # вхолостую каждую ночь — платить блокировкой ни за что.
    if config.is_sqlite() and removed:
        before, after, why = await vacuum_sqlite()
        if why:
            parts.append(f"без сжатия ({why})")
        elif after < before:
            parts.append(f"освобождено {format_size(before - after)}")

    try:
        await repo.set_meta("dbcare_last_run", now.strftime("%Y-%m-%d"))
    except Exception:  # noqa: BLE001
        # Отметку не записали — завтра обслужим ещё раз. Это безвреднее,
        # чем не обслужить вовсе.
        log.warning("Отметка об обслуживании базы не сохранилась")

    return "; ".join(parts)
